-- Retained draft accounts may be inactive OR nonpostable, matching the service.
DROP TRIGGER fb_check_line_insert;
CREATE TRIGGER fb_check_line_insert BEFORE INSERT ON checks_checkline BEGIN
 SELECT RAISE(ABORT,'check_history_immutable: Check lines are immutable') WHERE EXISTS(SELECT 1 FROM checks_checkline WHERE id=NEW.id OR (revision_id=NEW.revision_id AND position=NEW.position));
 SELECT RAISE(ABORT,'check_line_scope: Invalid check line scope or committed history') WHERE NOT EXISTS(SELECT 1 FROM checks_checkrevision r JOIN checks_check c ON c.id=r.document_id WHERE r.id=NEW.revision_id AND r.number=c.revision AND NOT EXISTS(SELECT 1 FROM fb_seal WHERE kind='check_revision' AND doc_id=c.id||':'||c.revision) AND (NEW.item_id IS NULL OR EXISTS(SELECT 1 FROM directory_item WHERE id=NEW.item_id AND company_id=c.company_id)) AND (NEW.account_id IS NULL OR EXISTS(SELECT 1 FROM ledger_account WHERE id=NEW.account_id AND company_id=c.company_id)));
 SELECT RAISE(ABORT,'check_line_calculation: Invalid check line calculation or shape') WHERE fb_payables_line_valid(NEW.quantity,NEW.rate,NEW.amount)=0 OR (NEW.tab='EXPENSE' AND (NEW.item_id IS NOT NULL OR NEW.quantity<>10000)) OR (NEW.tab='ITEM' AND NEW.item_id IS NULL);
 SELECT RAISE(ABORT,'check_item_eligible: New draft items must be active') WHERE NEW.item_id IS NOT NULL AND EXISTS(SELECT 1 FROM checks_checkrevision WHERE id=NEW.revision_id AND state='DRAFT') AND NOT EXISTS(SELECT 1 FROM directory_item i JOIN checks_checkrevision r ON r.id=NEW.revision_id WHERE i.id=NEW.item_id AND (i.active=1 OR EXISTS(SELECT 1 FROM checks_checkrevision p JOIN checks_checkline l ON l.revision_id=p.id WHERE p.document_id=r.document_id AND p.number=r.number-1 AND l.item_id=i.id)));
 SELECT RAISE(ABORT,'check_line_eligible: Invalid draft purchase account') WHERE NEW.account_id IS NOT NULL AND EXISTS(SELECT 1 FROM checks_checkrevision WHERE id=NEW.revision_id AND state='DRAFT') AND NOT EXISTS(SELECT 1 FROM checks_checkrevision r JOIN checks_check c ON c.id=r.document_id JOIN ledger_account a ON a.company_id=c.company_id WHERE r.id=NEW.revision_id AND a.id=NEW.account_id AND a.id<>r.bank_id AND a.detail_type IN('BANK','OTHER_CURRENT_ASSET','FIXED_ASSET','OTHER_ASSET','CREDIT_CARD','OTHER_CURRENT_LIABILITY','LONG_TERM_LIABILITY','EQUITY','COST_OF_GOODS_SOLD','EXPENSE','OTHER_EXPENSE') AND NOT EXISTS(SELECT 1 FROM fb_control_accounts WHERE company_id=c.company_id AND account_id=a.id) AND ((a.active=1 AND a.postable=1) OR EXISTS(SELECT 1 FROM checks_checkrevision p JOIN checks_checkline l ON l.revision_id=p.id WHERE p.document_id=c.id AND p.number=r.number-1 AND l.account_id=a.id)));
END;
CREATE TRIGGER fb_checks_check_existing_parent BEFORE INSERT ON checks_check WHEN NOT EXISTS(SELECT 1 FROM ledger_account WHERE id=NEW.bank_id AND company_id=NEW.company_id) OR (NEW.vendor_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM directory_vendor WHERE id=NEW.vendor_id AND company_id=NEW.company_id)) BEGIN SELECT RAISE(ABORT,'checks_existing_parent: Referenced parent must already exist'); END;
CREATE TRIGGER fb_checks_checkrevision_existing_parent BEFORE INSERT ON checks_checkrevision WHEN NOT EXISTS(SELECT 1 FROM fb_user WHERE id=NEW.actor_id) BEGIN SELECT RAISE(ABORT,'checks_existing_parent: Referenced parent must already exist'); END;
CREATE TRIGGER fb_transfers_transfer_existing_parent BEFORE INSERT ON transfers_transfer WHEN NOT EXISTS(SELECT 1 FROM fb_user WHERE id=NEW.actor_id) BEGIN SELECT RAISE(ABORT,'checks_existing_parent: Referenced parent must already exist'); END;
CREATE TRIGGER fb_transfers_transfervoid_existing_parent BEFORE INSERT ON transfers_transfervoid WHEN NOT EXISTS(SELECT 1 FROM fb_user WHERE id=NEW.actor_id) BEGIN SELECT RAISE(ABORT,'checks_existing_parent: Referenced parent must already exist'); END;
